function createLRU(maxSize) {
  const cache = new Map()
  return {
    get: (key) => {
      if (!cache.has(key)) return -1
      const val = cache.get(key)
      cache.delete(key)
      cache.set(key, val)
      return val
    },
    set: (key, value) => {
      cache.delete(key)
      if (cache.size >= maxSize) {
        cache.delete(cache.keys().next().value)
      }
      cache.set(key, value)
    }
  }
}
